import { URL, URLSearchParams, TextEncoder, TextDecoder, AbortController, install } from './index.js';

const u = new URL('https://example.com/a?b=1');
if (u.hostname !== 'example.com') throw new Error('URL failed');
print('ok   globals.URL');

const p = new URLSearchParams('a=1&b=2');
if (p.get('b') !== '2') throw new Error('URLSearchParams failed');
print('ok   globals.URLSearchParams');

const bytes = new TextEncoder().encode('halo');
if (bytes.length !== 4 || bytes[0] !== 0x68) throw new Error('TextEncoder failed');
if (new TextDecoder().decode(bytes) !== 'halo') throw new Error('TextDecoder failed');
print('ok   globals.TextEncoder/TextDecoder');

const dest = new Uint8Array(8);
const result = new TextEncoder().encodeInto('abc', dest);
if (result.written !== 3 || dest[0] !== 0x61) throw new Error('encodeInto failed');
print('ok   globals.encodeInto');

const controller = new AbortController();
let aborted = false;
controller.signal.addEventListener('abort', () => { aborted = true; });
controller.abort();
if (!controller.signal.aborted || !aborted) throw new Error('AbortController failed');
print('ok   globals.AbortController');

const target = {};
install(target);
if (typeof target.setTimeout !== 'function' || typeof target.URL !== 'function') throw new Error('install failed');
print('ok   globals.install');
print('ALL_OK');
